namespace model {

// Helper function to compute the bivariate normal distribution
// Using the approximation from Hagan et al. (2002)
inline double bivariate_normal(double x, double y, double rho) {
    // For numerical stability, we use the approximation for small rho
    if (std::abs(rho) < 1e-6) {
        return std::exp(-0.5 * (x*x + y*y)) / (2 * M_PI);
    }

    // Use the standard bivariate normal CDF approximation
    // This is a simplified version - in practice, one would use a more robust implementation
    double denom = std::sqrt(1 - rho*rho);
    double z1 = (x - rho*y) / denom;
    double z2 = (y - rho*x) / denom;
    return std::exp(-0.5 * (x*x + y*y - 2*rho*x*y)) / (2 * M_PI * denom);
}

// Hagan's SABR implied volatility formula with smooth ATMF handling
double sabr_vol(double F, double K, double T, const SabrParams& p) {
    // Validate inputs
    if (F <= 0 || K <= 0 || T <= 0) {
        throw std::invalid_argument("F, K, and T must be positive");
    }

    const double alpha = p.alpha;
    const double beta = p.beta;
    const double rho = p.rho;
    const double nu = p.nu;

    if (alpha <= 0 || nu < 0) {
        throw std::invalid_argument("alpha must be positive and nu must be non-negative");
    }

    if (std::abs(rho) >= 1) {
        throw std::invalid_argument("rho must satisfy |rho| < 1");
    }

    // Special case: if nu = 0, return Black volatility
    if (nu < 1e-12) {
        double vol = alpha / (F * (1 + (K - F) / F));
        return vol;
    }

    // Hagan's formula for lognormal SABR
    double z = alpha * std::pow(F * K, (1 - beta) / 2) / nu;
    double x = std::log(F / K);

    // Handle the case when K = F (ATM)
    if (std::abs(x) < 1e-12) {
        // Use the ATMF (at-the-money forward) form
        double A = 1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T;
        double B = 1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T;
        double C = 1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T;
        double D = 1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T;
        double vol = alpha * (1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T) / (F * (1 + (K - F) / F));
        return vol;
    }

    // Standard case
    double y = std::log(F / K);
    double x = std::log(F / K);

    // Hagan's expansion coefficients
    double A = 1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T;
    double B = 1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T;
    double C = 1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T;
    double D = 1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T;

    // Use the standard Hagan expansion
    double z = alpha * std::pow(F * K, (1 - beta) / 2) / nu;
    double x = std::log(F / K);

    // For numerical stability, we use the smooth approximation
    double numerator = alpha * std::pow(F * K, (1 - beta) / 2);
    double denominator = nu * (1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T);

    // Use the smooth version for K near F
    if (std::abs(x) < 1e-6) {
        double vol = alpha * (1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T) / (F * (1 + (K - F) / F));
        return vol;
    }

    // Standard Hagan formula
    double vol = numerator / denominator;
    return vol;
}

// Helper function to compute the implied volatility for a given set of parameters
double compute_implied_vol(double F, double K, double T, double alpha, double beta, double rho, double nu) {
    // This is a simplified version - in a full implementation, we'd use the full Hagan formula
    if (nu < 1e-12) {
        // Return Black volatility when nu is very small
        return alpha / (F * (1 + (K - F) / F));
    }

    // Use the standard Hagan formula
    double z = alpha * std::pow(F * K, (1 - beta) / 2) / nu;
    double x = std::log(F / K);

    // For K = F, use ATMF formula
    if (std::abs(x) < 1e-12) {
        double vol = alpha * (1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T) / (F * (1 + (K - F) / F));
        return vol;
    }

    // Standard case
    double numerator = alpha * std::pow(F * K, (1 - beta) / 2);
    double denominator = nu * (1 + (1 - beta) * (1 - beta) / 24 * std::pow(alpha, 2) * T);
    return numerator / denominator;
