SabrParams sabr_calibrate(double F, double T, double beta, const std::vector<double>& strikes, const std::vector<double>& vols) {
    // Validate inputs
    if (F <= 0 || T <= 0) {
        throw std::invalid_argument("F and T must be positive");
    }

    if (strikes.size() < 3 || vols.size() < 3) {
        throw std::invalid_argument("At least 3 quotes required for calibration");
    }

    if (strikes.size() != vols.size()) {
        throw std::invalid_argument("Strike and vol vectors must have the same size");
    }

    // Check for positive values
    for (size_t i = 0; i < strikes.size(); ++i) {
        if (strikes[i] <= 0 || vols[i] <= 0) {
            throw std::invalid_argument("All strikes and volatilities must be positive");
        }
    }

    // Simple calibration approach using least squares
    // We'll use a simple iterative approach to fit alpha, rho, nu
    // Initialize with reasonable values
    SabrParams result;
    result.alpha = 0.2;  // Initial guess for alpha
    result.rho = 0.0;    // Initial guess for rho
    result.nu = 0.5;     // Initial guess for nu

    // For beta, we keep it fixed as provided
    result.beta = beta;

    // Simple optimization using a basic gradient descent approach
    // This is a simplified version - a full implementation would use a more robust optimization method

    // We'll use a simple iterative approach with fixed steps
    const int max_iterations = 1000;
    const double tolerance = 1e-8;
    const double step_size = 0.01;

    // Simple optimization loop
    for (int iter = 0; iter < max_iterations; ++iter) {
        double total_error = 0.0;
        double grad_alpha = 0.0;
        double grad_rho = 0.0;
        double grad_nu = 0.0;

        // Compute gradients
        for (size_t i = 0; i < strikes.size(); ++i) {
            double vol = compute_implied_vol(F, strikes[i], T, result.alpha, result.beta, result.rho, result.nu);
            double error = vol - vols[i];
            total_error += error * error;

            // Simple finite difference gradients
            double eps = 1e-6;
            double vol_plus_alpha = compute_implied_vol(F, strikes[i], T, result.alpha + eps, result.beta, result.rho, result.nu);
            double vol_plus_rho = compute_implied_vol(F, strikes[i], T, result.alpha, result.beta, result.rho + eps, result.nu);
            double vol_plus_nu = compute_implied_vol(F, strikes[i], T, result.alpha, result.beta, result.rho, result.nu + eps);

            grad_alpha += 2 * error * (vol_plus_alpha - vol) / eps;
            grad_rho += 2 * error * (vol_plus_rho - vol) / eps;
            grad_nu += 2 * error * (vol_plus_nu - vol) / eps;
        }

        // Update parameters
        result.alpha -= step_size * grad_alpha;
        result.rho -= step_size * grad_rho;
        result.nu -= step_size * grad_nu;

        // Ensure constraints
        result.alpha = std::max(1e-10, result.alpha);  // alpha > 0
        result.rho = std::clamp(result.rho, -0.999, 0.999);  // |rho| < 1
        result.nu = std::max(0.0, result.nu);  // nu >= 0

        // Check convergence
        if (total_error < tolerance) {
            break;
        }
    }

    // Final validation
    if (result.alpha <= 0 || result.nu < 0 || std::abs(result.rho) >= 1) {
        // If we failed to converge to valid parameters, return reasonable defaults
        result.alpha = 0.2;
        result.rho = 0.0;
        result.nu = 0.5;
    }

    return result;
}

}  // namespace model

